package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen4Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter out;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        out = new StringWriter();
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        int result = unescaper.translate("abc", 0, out);
        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_NotEntity() throws IOException {
        // Just an '&' at the end
        int result = unescaper.translate("&", 0, out);
        assertEquals(0, result);

        // '&' but not followed by '#'
        result = unescaper.translate("&a", 0, out);
        assertEquals(0, result);
    }

    @Test
    public void testTranslate_DecimalSmall() throws IOException {
        // &#60; is '<'
        int result = unescaper.translate("&#60;", 0, out);
        assertEquals(5, result); // 2 ('&#') + 2 ('60') + 1 (';')
        assertEquals("<", out.toString());
    }

    @Test
    public void testTranslate_DecimalLarge() throws IOException {
        // &#128512; is 😀 (Surrogate pair)
        int result = unescaper.translate("&#128512;", 0, out);
        assertEquals(8, result); // 2 + 5 + 1
        assertEquals("😀", out.toString());
    }

    @Test
    public void testTranslate_HexLowercase() throws IOException {
        // &#x3c; is '<'
        int result = unescaper.translate("&#x3c;", 0, out);
        assertEquals(6, result); // 2 + 3 (x3c) + 1
        assertEquals("<", out.toString());
    }

    @Test
    public void testTranslate_HexUppercase() throws IOException {
        // &#X3C; is '<'
        int result = unescaper.translate("&#X3C;", 0, out);
        assertEquals(6, result);
        assertEquals("<", out.toString());
    }

    @Test
    public void testTranslate_HexLarge() throws IOException {
        // &#x1F600; is 😀
        int result = unescaper.translate("&#x1F600;", 0, out);
        assertEquals(8, result);
        assertEquals("😀", out.toString());
    }

    @Test
    public void testTranslate_NumberFormatException_Decimal() throws IOException {
        // Invalid decimal characters
        int result = unescaper.translate("&#abc;", 0, out);
        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_NumberFormatException_Hex() throws IOException {
        // Invalid hex characters (g is not hex)
        int result = unescaper.translate("&#xg;", 0, out);
        assertEquals(0, result);
        assertEquals("", out.toString());
    }

    @Test
    public void testTranslate_IndexOffset() throws IOException {
        // Test translating from a specific index in a larger string
        int result = unescaper.translate("prefix&#60;suffix", 6, out);
        assertEquals(5, result);
        assertEquals("<", out.toString());
    }

    @Test(expected = StringIndexOutOfBoundsException.class)
    public void testTranslate_OutOfBounds_WhileLoop() throws IOException {
        // This test targets the while loop condition if the ';' is missing 
        // and it hits the end of the string, causing StringIndexOutOfBoundsException.
        // The original code does not check for end of string inside the while loop.
        unescaper.translate("&#60", 0, out);
    }
}
